/**
 * Builds the `/comments/allow` page's picker script: type-checks `picker.ts` against the DOM,
 * then bundles it with esbuild into `../picker-script.generated.ts`, a string constant the page
 * serves at `/comments/allow/picker.js`.
 *
 *   npx tsx mcp/sasha-slides/comment-bot/access-browser/build.ts          (from the repo root)
 *
 * WHY A CHECKED-IN GENERATED FILE rather than bundling at server start: esbuild is a
 * development dependency of the repo, not a runtime dependency of the connector image, and a
 * generated TypeScript module is reached through an ordinary import, so the deploy ships it with
 * no list to edit (the same pattern as `http/passkey-browser/build.ts`).
 * `test/comment-access-page.test.ts` fails when the generated file no longer matches its source.
 */
import { execFileSync } from "node:child_process";
import { writeFileSync } from "node:fs";
import { join, resolve } from "node:path";
import { build } from "esbuild";

export const PICKER_SCRIPT_SOURCE = join(import.meta.dirname, "picker.ts");
export const PICKER_SCRIPT_MODULE = join(import.meta.dirname, "..", "picker-script.generated.ts");
const REPO_ROOT = join(import.meta.dirname, "..", "..", "..", "..");

/** The generated module's full text, from the current source. */
export async function renderPickerScriptModule(): Promise<string> {
  const result = await build({
    // Fixed, so the source path esbuild writes into the output does not depend on the caller's cwd.
    absWorkingDir: REPO_ROOT,
    entryPoints: [PICKER_SCRIPT_SOURCE],
    bundle: true,
    format: "iife",
    platform: "browser",
    target: "es2020",
    minify: false,
    write: false,
    logLevel: "error",
  });
  const code = result.outputFiles[0]?.text;
  if (code === undefined) throw new Error(`esbuild produced no output for ${PICKER_SCRIPT_SOURCE}`);
  return `// Generated by comment-bot/access-browser/build.ts from comment-bot/access-browser/picker.ts. Do not edit.\nexport const PICKER_SCRIPT = ${JSON.stringify(code)};\n`;
}

async function main(): Promise<void> {
  // esbuild strips types without checking them, so the check is its own failing step first.
  execFileSync(join(REPO_ROOT, "node_modules", ".bin", "tsc"), ["--noEmit", "-p", import.meta.dirname], { stdio: "inherit" });
  writeFileSync(PICKER_SCRIPT_MODULE, await renderPickerScriptModule());
  process.stdout.write(`wrote ${PICKER_SCRIPT_MODULE}\n`);
}

if (process.argv[1] !== undefined && resolve(process.argv[1]) === import.meta.filename) void main();
